begin;
insert into public.ce_course3_resources(id,data) values
('course3_module8_pdf','{"base64": "", "sha256": "843fb75317d453d45fd263234acedcd715a3e461a52f18ec7e4644847cee41d0", "filename": "CE_HALO_Course3_Module08_Obstetric_Liability_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module8_questions','[{"module_id": "course_3_module_8", "question_id": "course_3_module_8_q01", "question_number": 1, "stem": "According to the CDC, the U.S. maternal mortality rate in 2022 was approximately:", "choice_a": "22.3 deaths per 100,000 live births", "choice_b": "132 deaths per 100,000 live births", "choice_c": "5.4 deaths per 100,000 live births", "choice_d": "60.1 deaths per 100,000 live births", "correct_choice": "a", "rationale": "The CDC/NCHS reported a U.S. maternal mortality rate of 22.3 per 100,000 live births in 2022 — down from the pandemic-era peak of 32.9 in 2021 but still substantially higher than most peer nations, with a persistent 2.6× disparity for Black non-Hispanic mothers.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q02", "question_number": 2, "stem": "Per the SOAP/AHA consensus and the 2023 AHA focused update, perimortem cesarean delivery during maternal cardiac arrest should ideally be:", "choice_a": "Deferred until fetal viability is confirmed by ultrasound", "choice_b": "Decided at 4 minutes of arrest with delivery achieved by 5 minutes if there is no return of spontaneous circulation", "choice_c": "Performed only if the fetus is ≥ 34 weeks", "choice_d": "Delayed until the anesthesiologist arrives", "correct_choice": "b", "rationale": "SOAP (Lipman et al., 2014) and the 2023 AHA guidelines recommend perimortem cesarean decision at 4 minutes and delivery by 5 minutes if no ROSC — regardless of fetal viability — to relieve aortocaval compression and improve maternal survival.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q03", "question_number": 3, "stem": "During maternal cardiac arrest, current SOAP/AHA guidance recommends:", "choice_a": "Left lateral tilt of the table at 30°", "choice_b": "Reduced epinephrine dosing to protect the fetus", "choice_c": "Manual left uterine displacement with the patient supine on a firm surface, IV access above the diaphragm, and standard ACLS drug doses", "choice_d": "Avoiding defibrillation until after delivery", "correct_choice": "c", "rationale": "Table tilt degrades chest compression quality. AHA 2023 and SOAP recommend manual LUD, supine positioning, IV access above the diaphragm (to avoid aortocaval interference), standard ACLS drug doses, and standard defibrillation energy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q04", "question_number": 4, "stem": "A 32-year-old parturient develops sudden hypoxemia, hypotension, seizure, and DIC 5 minutes after spontaneous vaginal delivery. Which diagnosis best fits the SMFM/AFE Foundation clinical criteria for amniotic fluid embolism?", "choice_a": "Neuraxial-related hypotension", "choice_b": "Any cardiovascular collapse during labor", "choice_c": "Isolated postpartum hemorrhage with hypotension", "choice_d": "Sudden cardiorespiratory arrest or hypotension with respiratory compromise, followed by overt DIC, occurring during labor or within 30 minutes of placental delivery, with no fever ≥ 38 °C", "correct_choice": "d", "rationale": "Clark et al. (2016), reaffirmed in the 2023 SMFM consult, define AFE by all four criteria: cardiorespiratory arrest or hypotension with respiratory compromise, overt DIC after the initial signs, onset during labor or within 30 minutes of placental delivery, and no fever ≥ 38 °C during labor.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q05", "question_number": 5, "stem": "Under the 2021 SOAP interdisciplinary consensus on neuraxial procedures in obstetric patients with thrombocytopenia, neuraxial anesthesia is generally considered reasonable when the platelet count is:", "choice_a": "≥ 70 × 10⁹/L, stable, with no additional bleeding risk factors", "choice_b": "≥ 150 × 10⁹/L", "choice_c": "≥ 50 × 10⁹/L with no additional risk factors", "choice_d": "≥ 20 × 10⁹/L", "correct_choice": "a", "rationale": "The 2021 SOAP consensus (Bauer et al.) considers neuraxial reasonable at a stable platelet count ≥ 70 × 10⁹/L with no additional risk factors; 50–70 × 10⁹/L requires individualization; < 50 generally favors alternatives.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q06", "question_number": 6, "stem": "A laboring patient develops sudden numbness ascending to the shoulders, dyspnea, dysphonia, and BP 68/32 five minutes after an epidural top-up. The MOST appropriate immediate CRNA action is to:", "choice_a": "Administer additional epidural anesthetic to “break through” the block", "choice_b": "Call for help; support ventilation and consider intubation; administer phenylephrine/ephedrine, IV fluid, and left uterine displacement; notify OB and neonatal teams", "choice_c": "Continue observation because these symptoms often resolve", "choice_d": "Reverse the epidural with intralipid immediately without other supportive care", "correct_choice": "b", "rationale": "Findings are classic for high or total spinal anesthesia. Immediate response is airway support, vasopressor and fluid resuscitation, LUD, and OB/neonatal notification. Lipid is not the primary treatment for high spinal (it is for LAST).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q07", "question_number": 7, "stem": "Which of the following is the FIRST-LINE pharmacologic treatment for local anesthetic systemic toxicity (LAST) per ASRA 2020 (updated 2023) guidance?", "choice_a": "Vasopressin", "choice_b": "Standard 1 mg IV epinephrine bolus", "choice_c": "20% lipid emulsion 1.5 mL/kg lean body weight bolus followed by 0.25 mL/kg/min infusion, with epinephrine limited to ≤ 1 mcg/kg boluses", "choice_d": "Calcium channel blockers", "correct_choice": "c", "rationale": "ASRA recommends immediate 20% lipid emulsion 1.5 mL/kg bolus followed by 0.25 mL/kg/min, with epinephrine dosing reduced to ≤ 1 mcg/kg boluses and avoidance of vasopressin, calcium channel blockers, and beta-blockers.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q08", "question_number": 8, "stem": "A parturient with a labor epidural that has required frequent boluses for a unilateral block now needs a Category 1 (crash) cesarean for fetal bradycardia. The MOST liability-defensible anesthetic plan is generally to:", "choice_a": "Perform a spinal on top of the existing epidural without any dose reduction", "choice_b": "Delay surgery to place a new epidural", "choice_c": "Rebolus the epidural and hope for adequate conversion", "choice_d": "Proceed with general anesthesia via rapid-sequence induction with video laryngoscopy, cricoid per policy, and difficult-airway backup immediately available", "correct_choice": "d", "rationale": "A poorly functioning labor epidural is unlikely to convert reliably. For a true crash cesarean, general anesthesia with difficult-airway readiness is safer than repeated attempts to salvage an unreliable block, and delay is not acceptable in a Category 1 setting.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q09", "question_number": 9, "stem": "Per ACOG Practice Bulletin No. 205 (reaffirmed), a trial of labor after cesarean (TOLAC) should be offered ONLY in facilities that have:", "choice_a": "Immediate availability of anesthesia personnel and the ability to begin cesarean delivery expeditiously if uterine rupture occurs", "choice_b": "A dedicated obstetric ICU", "choice_c": "Board-certified anesthesiologists on call from home", "choice_d": "Only CRNAs credentialed in cardiac anesthesia", "correct_choice": "a", "rationale": "ACOG PB 205 explicitly requires immediate availability of anesthesia and the ability to begin cesarean delivery expeditiously; the guidance is driven by the rapid decision-to-incision requirement in uterine rupture.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q10", "question_number": 10, "stem": "A patient with a suspected accidental dural puncture during labor epidural placement develops a bilateral throbbing headache 24 hours postpartum that improves when supine and worsens when upright. Which additional feature would MOST require urgent evaluation for an alternative diagnosis rather than routine PDPH management?", "choice_a": "Onset 24 hours after neuraxial placement", "choice_b": "New focal neurologic deficit, seizure, altered mental status, or a thunderclap or non-positional pattern", "choice_c": "Neck stiffness and mild tinnitus", "choice_d": "Photophobia", "correct_choice": "b", "rationale": "Per the 2023 international PDPH consensus, atypical features — focal neurologic deficits, seizure, altered mental status, thunderclap or non-positional headache — require urgent evaluation for preeclampsia, ICH, CVST, meningitis, subdural hematoma, or PRES/RCVS.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q11", "question_number": 11, "stem": "Per ACOG Practice Bulletin No. 183, postpartum hemorrhage is defined as:", "choice_a": "Blood loss requiring ≥ 4 units RBC only", "choice_b": "Any blood loss > 250 mL", "choice_c": "Cumulative blood loss ≥ 1,000 mL OR blood loss accompanied by signs or symptoms of hypovolemia within 24 hours after birth, regardless of delivery route", "choice_d": "Blood loss > 500 mL after vaginal delivery only", "correct_choice": "c", "rationale": "ACOG PB 183 defines PPH as cumulative blood loss ≥ 1,000 mL or blood loss with hypovolemia signs within 24 hours regardless of delivery route, unifying the prior separate vaginal and cesarean thresholds.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q12", "question_number": 12, "stem": "Per WOMAN Trial and current ACOG/WHO guidance, tranexamic acid (TXA) for postpartum hemorrhage should be administered:", "choice_a": "Only for uterine atony", "choice_b": "Only after 4 units of blood have been transfused", "choice_c": "Only for hemorrhage after cesarean", "choice_d": "1 g IV within 3 hours of hemorrhage onset, with a second 1 g dose if bleeding continues after 30 minutes", "correct_choice": "d", "rationale": "The WOMAN Trial (2017) showed reduced maternal death from bleeding when TXA 1 g IV was administered within 3 hours of PPH onset; a repeat dose can be given if bleeding continues.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q13", "question_number": 13, "stem": "Contemporary obstetric anesthesia guidance identifies which vasopressor as generally FIRST-LINE for treating spinal-induced hypotension at elective cesarean delivery?", "choice_a": "Phenylephrine, often as a prophylactic infusion", "choice_b": "Vasopressin", "choice_c": "Ephedrine", "choice_d": "Norepinephrine 32 mcg/mL bolus dosing", "correct_choice": "a", "rationale": "Contemporary evidence and SOAP/ASA guidance favor phenylephrine as first-line (frequently as a prophylactic infusion) because it preserves uteroplacental perfusion better than ephedrine and reduces neonatal acidosis.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q14", "question_number": 14, "stem": "Per the RCOG four-category framework widely adopted in the U.S., a Category 1 cesarean delivery indicates:", "choice_a": "An elective cesarean at term", "choice_b": "Immediate threat to life of mother or fetus; decision-to-incision goal is typically ≤ 15–30 minutes", "choice_c": "Delivery needed within a few days but not urgent", "choice_d": "Maternal request without medical indication", "correct_choice": "b", "rationale": "Category 1 is immediate threat to life of mother or fetus, with decision-to-incision typically ≤ 15–30 minutes; Category 2 involves compromise but not immediately life-threatening; Category 3 requires early delivery without compromise; Category 4 is elective.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q15", "question_number": 15, "stem": "In the AANA Foundation obstetric closed-claims review (Clayton et al., 2018), the leading identified cause of MATERNAL death was:", "choice_a": "Failed intubation", "choice_b": "High spinal", "choice_c": "Hemorrhage", "choice_d": "PDPH", "correct_choice": "c", "rationale": "Clayton et al. (2018) identified hemorrhage as the leading cause of maternal death in AANA Foundation obstetric closed claims, with recurring themes of care delay, communication failure, and incomplete documentation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q16", "question_number": 16, "stem": "In the Kovacheva et al. (2019) contemporary medicolegal review of 106 obstetric anesthesia claims (2005–2015), the SINGLE LARGEST claim category was:", "choice_a": "PDPH", "choice_b": "Maternal death", "choice_c": "Newborn death", "choice_d": "Maternal nerve injury", "correct_choice": "d", "rationale": "Kovacheva et al. (2019) found maternal nerve injury was the largest single claim category, while maternal death or brain injury claims were more likely to result in payment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q17", "question_number": 17, "stem": "A patient with severe preeclampsia has BP 172/112 that has persisted for 20 minutes. Per current ACOG/AIM guidance, IV antihypertensive therapy should generally be initiated within:", "choice_a": "30–60 minutes", "choice_b": "5 minutes", "choice_c": "6 hours", "choice_d": "24 hours", "correct_choice": "a", "rationale": "Persistent severe-range hypertension (SBP ≥ 160 or DBP ≥ 110 for ≥ 15 minutes) is an obstetric emergency; ACOG/AIM safety bundles require initiation of IV antihypertensive (labetalol, hydralazine, or nifedipine per protocol) within 30–60 minutes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q18", "question_number": 18, "stem": "During emergency cesarean delivery under general anesthesia, which strategy BEST reduces the risk of intraoperative awareness in the obstetric patient?", "choice_a": "Avoid volatile anesthetics entirely", "choice_b": "Use adequate induction dosing, transition rapidly to volatile anesthetic ≥ 0.5 MAC after intubation, and consider low-dose midazolam after delivery", "choice_c": "Rely only on high-dose opioid", "choice_d": "Underdose induction agents to minimize neonatal drug exposure", "correct_choice": "b", "rationale": "Underdosing induction agents — out of concern for neonatal effects — is a leading cause of awareness. Adequate induction, rapid transition to volatile anesthetic ≥ 0.5 MAC, and consideration of midazolam post-delivery are recommended by NAP5 obstetric findings.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q19", "question_number": 19, "stem": "During cesarean delivery under neuraxial anesthesia, the patient reports sharp intolerable pain at incision. The MOST liability-defensible next step is to:", "choice_a": "Ask the family to reassure the patient", "choice_b": "Give an oral sedative", "choice_c": "Immediately acknowledge the complaint, notify the surgeon, assess the block, treat pain (supplemental analgesia), consider conversion to general anesthesia when appropriate, and document the assessment, treatment, and communication", "choice_d": "Reassure the patient and continue surgery to expedite delivery", "correct_choice": "c", "rationale": "Kovacheva et al. and other closed-claims data identify dismissing patient-reported pain as a major liability driver. Immediate acknowledgment, assessment, treatment, and, when appropriate, conversion to GA are required.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q20", "question_number": 20, "stem": "Which of the following BEST reflects the CRNA’s appropriate role in fetal heart-rate tracing documentation on the anesthesia record?", "choice_a": "The CRNA should ignore FHR data", "choice_b": "The CRNA should provide the primary FHR interpretation", "choice_c": "The CRNA should copy the FHR tracing image into the anesthesia record", "choice_d": "The CRNA should document what was communicated by nursing or OB, relevant maternal physiologic changes, interventions performed, and team response — without making definitive obstetric FHR interpretations unless credentialed to do so", "correct_choice": "d", "rationale": "Unless credentialed for FHR interpretation under facility policy, the CRNA should record what was communicated by OB/nursing, what maternal physiology was observed, and what anesthesia interventions were performed — not independent FHR interpretations.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q21", "question_number": 21, "stem": "Per ACOG Levels of Maternal Care and most facility policies, a Level III or IV birthing center should have:", "choice_a": "In-house anesthesia coverage 24 hours a day, 7 days a week", "choice_b": "Anesthesia only for cesarean deliveries", "choice_c": "Anesthesia on call from home", "choice_d": "Anesthesia available within 60 minutes", "correct_choice": "a", "rationale": "ACOG/SMFM Levels of Maternal Care (Obstetric Care Consensus No. 9) expects Level III/IV facilities to have in-house anesthesia 24/7 because these centers manage the highest-acuity maternal cases.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q22", "question_number": 22, "stem": "Which practice BEST supports culturally responsive, legally defensible informed consent for obstetric anesthesia in a patient with limited English proficiency?", "choice_a": "Have the patient sign a translated form without discussion", "choice_b": "Use a qualified medical interpreter (in-person, phone, or video), confirm understanding with teach-back, and document the interpreter name/vendor and language", "choice_c": "Ask the patient’s spouse to translate consent", "choice_d": "Use gestures and simplified English only", "correct_choice": "b", "rationale": "Family members should not translate complex anesthesia consent — they may omit, soften, or alter information. Qualified interpreters, teach-back, and documentation of interpreter use are required and are also mandated under Section 1557 of the ACA.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q23", "question_number": 23, "stem": "A patient with suspected placenta accreta spectrum is scheduled for cesarean hysterectomy. Which anesthesia plan is MOST consistent with contemporary SMFM/SOAP guidance?", "choice_a": "Neuraxial anesthesia is contraindicated in all PAS cases", "choice_b": "Routine spinal only, no additional preparation", "choice_c": "Delivery at a facility with 24-hour blood bank and MTP, two large-bore IVs plus arterial line, cell salvage availability, blood-product pre-positioning, multidisciplinary team, and planned ICU postoperative care — with a low threshold to convert to GA if hemorrhage becomes severe", "choice_d": "General anesthesia is always required", "correct_choice": "c", "rationale": "Contemporary SMFM/SOAP guidance supports management at a PAS-experienced Level III/IV center with pre-positioned blood products, invasive monitoring, cell salvage, multidisciplinary team readiness, and planned ICU care. Neuraxial with low threshold to convert to GA is often appropriate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q24", "question_number": 24, "stem": "A CRNA discovers that a labor epidural placed 2 hours ago has provided only unilateral analgesia and required repeated boluses. The patient may need cesarean delivery for arrest of labor. The MOST proactive risk-management action is to:", "choice_a": "Document the block as “adequate” to avoid a chart flag", "choice_b": "Wait until the surgical decision is made before troubleshooting", "choice_c": "Continue the epidural and hope it works if needed", "choice_d": "Reassess the catheter now, troubleshoot position, and replace proactively if the block remains inadequate — rather than relying on it in an emergency", "correct_choice": "d", "rationale": "Closed-claims data (ASA, AANA Foundation, Kovacheva) all identify failed epidural conversion as a major preventable risk. Proactive troubleshooting or replacement before an emergency is far safer than reactive management under crash conditions.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_8", "question_id": "course_3_module_8_q25", "question_number": 25, "stem": "Which of the following is the MOST accurate summary of the unifying message from ASA, AANA Foundation, and Kovacheva 2019 closed-claims data on obstetric anesthesia?", "choice_a": "Most obstetric anesthesia liability arises from system failures — delay, communication, documentation, and failure to convert a warning into escalation — rather than knowledge failure", "choice_b": "Most obstetric anesthesia liability is driven by patient refusal of care", "choice_c": "Most obstetric anesthesia liability is unrelated to CRNA practice", "choice_d": "Most obstetric anesthesia liability arises from lack of clinical knowledge", "correct_choice": "a", "rationale": "Across databases, the dominant preventable themes are delay, communication failure, incomplete documentation, and failure to escalate — system issues — rather than individual knowledge deficits. Anticipation, escalation, closed-loop communication, and contemporaneous documentation are the defensive keys.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module8_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;